package expression
import "testing"
func draft()*Document{return &Document{SchemaVersion:SchemaVersion,Status:StatusDraft,Source:Source{Type:"image",SHA256:"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"},Creator:Creator{OwnerID:"creator-1",Consent:true,Visibility:VisibilityPrivate},Mode:ModeWhatIf}}
func TestDraftRequiresProvenanceAndConsent(t *testing.T){d:=draft();if err:=d.Validate();err!=nil{t.Fatal(err)};d.Creator.Consent=false;if err:=d.Validate();err==nil{t.Fatal("expected consent failure")}}
func TestReadyRequiresTraceableInterpretation(t *testing.T){d:=draft();d.Status=StatusReady;d.Intent="A quiet world";d.ChosenInterpretation="A moon garden";d.Anchors=[]Anchor{{ID:"a1",Kind:"place",Value:"garden",Preserve:true}};d.Evidence=[]Evidence{{ID:"e1",Kind:"image_region",Start:0,End:1}};d.Interpretation.Preserved=[]Claim{{ID:"p1",Text:"garden",Confidence:.9,EvidenceIDs:[]string{"e1"}}};d.Generation=Generation{GameIRVersion:"1.2",PackageVersion:"2.0"};if err:=d.Validate();err!=nil{t.Fatal(err)};d.Interpretation.Preserved[0].EvidenceIDs=[]string{"missing"};if err:=d.Validate();err==nil{t.Fatal("expected unknown evidence failure")}}
func TestRemixRequiresParentAndModeIsAllowlisted(t *testing.T){d:=draft();d.Mode="other";if err:=d.Validate();err==nil{t.Fatal("expected invalid mode")};d.Mode=ModeRemix;if err:=d.Validate();err==nil{t.Fatal("expected missing parent")}}
